def find_max(lst):
    max_val = lst[0]
    for x in lst:
        if x > max_val:
            max_val = x
    return max_val

print(find_max([3, 9, 1, 7]))  # output: 9

def find_min(lst):
    min_val = lst[0]
    for x in lst:
        if x < min_val:
            min_val = x
    return min_val

print(find_min([5, 2, 8, 1]))  # output: 1

def average(lst):
    if not lst:
        return 0
    return sum(lst) / len(lst)

print(average([10, 20, 30]))  # output: 20.0

def sort_list(lst):
    arr = lst[:]
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[j] < arr[i]:
                arr[i], arr[j] = arr[j], arr[i]
    return arr

print(sort_list([3, 1, 2]))  # output: [1, 2, 3]

def remove_duplicates(lst):
    seen = []
    for x in lst:
        if x not in seen:
            seen.append(x)
    return seen

print(remove_duplicates([1, 2, 2, 3, 1]))  # output: [1, 2, 3]

def contains(lst, x):
    for item in lst:
        if item == x:
            return True
    return False

